{
  "name": "Cito Plus 1310 射频发生器",
  "name_en": "Cito Plus 1310 RF Generator",
  "manufacturer": "Comet",
  "description": "这是一台射频发生器，用于向实验装置或工艺负载提供可调射频功率，并监测正向功率、反射功率和负载功率等状态。适合需要稳定射频激励与功率控制的实验和设备集成场景。",
  "description_en": "This is an RF generator that provides adjustable radio-frequency power to an experimental system or process load, while monitoring forward, reflected, and load power. It is suited for laboratory and equipment-integration use cases that require stable RF excitation and controlled power delivery.",
  "tag_hints": [
    "RF generator",
    "radio-frequency power",
    "forward/reflected power monitoring",
    "output power control",
    "process load excitation",
    "RS-232 instrument control"
  ],
  "actions": [
    {
      "action_name": "auto-output_power",
      "description": "获取/设置输出功率设定值",
      "description_en": "Get/set the output power setpoint."
    },
    {
      "action_name": "auto-query",
      "description": "发送底层查询命令并读取设备响应",
      "description_en": "Send a low-level query command and read the device response."
    },
    {
      "action_name": "auto-regulation_mode",
      "description": "获取/设置功率调节模式",
      "description_en": "Get/set the regulation mode."
    },
    {
      "action_name": "auto-rf",
      "description": "获取/设置射频输出状态",
      "description_en": "Get/set the RF output state."
    },
    {
      "action_name": "auto-sendcmd",
      "description": "发送底层命令到设备",
      "description_en": "Send a low-level command to the device."
    },
    {
      "action_name": "auto-name",
      "description": "获取设备名称",
      "description_en": "Get the device name."
    },
    {
      "action_name": "auto-forward_power",
      "description": "获取正向功率",
      "description_en": "Get the forward power."
    },
    {
      "action_name": "auto-load_power",
      "description": "获取负载功率",
      "description_en": "Get the load power."
    },
    {
      "action_name": "auto-reflected_power",
      "description": "获取反射功率",
      "description_en": "Get the reflected power."
    }
  ]
}

